function drawGround(){ctx.fillStyle='#455842';ctx.fillRect(0,0,W,H); // broad woodland clearings
for(let i=0;i<areas.length;i++){let a=areas[i];let g=ctx.createRadialGradient(a.x,a.y,30,a.x,a.y,a.r*1.35);g.addColorStop(0,'rgba(130,131,91,.18)');g.addColorStop(1,'rgba(126,127,83,0)');ctx.fillStyle=g;ctx.fillRect(a.x-a.r*1.4,a.y-a.r*1.4,a.r*2.8,a.r*2.8)}
