ctx.lineCap='round';ctx.strokeStyle='#293f3d';ctx.lineWidth=92;ctx.beginPath();ctx.moveTo(2630,150);ctx.bezierCurveTo(2490,460,2720,650,2570,910);ctx.bezierCurveTo(2450,1170,2710,1320,2500,1580);ctx.bezierCurveTo(2400,1730,2540,1970,2450,2290);ctx.stroke();ctx.strokeStyle='#42615b';ctx.lineWidth=72;ctx.beginPath();ctx.moveTo(2630,150);ctx.bezierCurveTo(2490,460,2720,650,2570,910);ctx.bezierCurveTo(2450,1170,2710,1320,2500,1580);ctx.bezierCurveTo(2400,1730,2540,1970,2450,2290);ctx.stroke();ctx.strokeStyle='rgba(169,184,156,.22)';ctx.lineWidth=2;ctx.setLineDash([4,19]);ctx.beginPath();ctx.moveTo(2630,150);ctx.bezierCurveTo(2490,460,2720,650,2570,910);ctx.bezierCurveTo(2450,1170,2710,1320,2500,1580);ctx.stroke();ctx.setLineDash([]);
