}
function drawTree(t){if(t.x<camera.x-50||t.x>camera.x+cw+50||t.y<camera.y-50||t.y>camera.y+ch+50)return;let r=t.r;ctx.fillStyle='rgba(13,20,13,.32)';ctx.beginPath();ctx.ellipse(t.x+5,t.y+8,r*1.2,r*.76,0,0,7);ctx.fill();ctx.fillStyle=t.shade>.5?'#263a2b':'#30432d';ctx.beginPath();ctx.arc(t.x,t.y,r,0,Math.PI*2);ctx.fill();ctx.fillStyle=t.shade>.5?'#43563a':'#50613d';ctx.beginPath();ctx.arc(t.x-r*.18,t.y-r*.2,r*.73,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(160,160,103,.18)';ctx.beginPath();ctx.arc(t.x-r*.27,t.y-r*.35,r*.34,0,Math.PI*2);ctx.fill();ctx.fillStyle='#514b37';ctx.beginPath();ctx.arc(t.x+r*.15,t.y+r*.2,r*.19,0,Math.PI*2);ctx.fill()}
function drawBuilding(b){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.rot);ctx.fillStyle='rgba(8,12,9,.42)';ctx.fillRect(-b.w/2+8,-b.h/2+12,b.w,b.h);let wall=b.type==='clinic'?'#77766a':b.type==='military'?'#6a7055':b.type==='warehouse'?'#72705f':'#786d58';ctx.fillStyle='#4b4d40';ctx.fillRect(-b.w/2-3,-b.h/2-3,b.w+6,b.h+6);ctx.fillStyle=wall;ctx.fillRect(-b.w/2,-b.h/2,b.w,b.h);ctx.fillStyle=b.type==='shop'?'#514c40':b.type==='military'?'#414b3b':b.type==='warehouse'?'#56584e':'#564b3e';ctx.fillRect(-b.w/2+5,-b.h/2+5,b.w-10,b.h-10);ctx.strokeStyle='rgba(206,193,154,.25)';ctx.lineWidth=2;ctx.strokeRect(-b.w/2+5,-b.h/2+5,b.w-10,b.h-10);
// ridge roof seam, broken roof panels
ctx.strokeStyle='rgba(14,18,14,.6)';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-b.w*.36,-b.h*.22);ctx.lineTo(b.w*.36,b.h*.22);ctx.stroke();ctx.fillStyle='rgba(171,152,112,.25)';ctx.fillRect(-b.w*.3,-b.h*.3,b.w*.16,b.h*.11);ctx.fillStyle='#292d26';ctx.fillRect(-8,b.h/2-17,16,17);ctx.fillStyle='#89917b';ctx.fillRect(-b.w/2+12,-b.h/2+9,12,8);ctx.fillRect(b.w/2-24,-b.h/2+9,12,8);if(b.type==='shop'||b.type==='clinic'){ctx.fillStyle='#b9b497';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText(b.type==='shop'?'MARKET':'CLINIC',0,-b.h/2+16)}ctx.restore()}
function drawLoot(l){let blink=.5+.5*Math.sin(performance.now()/330+l.seed*9);ctx.save();ctx.globalAlpha=.55+blink*.35;ctx.fillStyle=l.id==='water'?'#a6d0bc':'#d7d79a';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=14;ctx.beginPath();ctx.arc(l.x,l.y,5+blink*2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#e7e6cb';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText(defs[l.id].icon,l.x,l.y-10);ctx.restore()}
function drawInfected(z){ctx.save();ctx.translate(z.x,z.y);ctx.rotate(z.angle);let bob=Math.sin(z.phase)*1.5;ctx.fillStyle='#11151077';ctx.beginPath();ctx.ellipse(1,8,14,8,0,0,7);ctx.fill();ctx.strokeStyle='#8c8a68';ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(13,8+bob);ctx.moveTo(0,0);ctx.lineTo(-8,-8-bob);ctx.stroke();ctx.fillStyle='#6b7355';ctx.beginPath();ctx.ellipse(0,0,7,11,0,0,7);ctx.fill();ctx.fillStyle='#b0a585';ctx.beginPath();ctx.arc(8,-1,5,0,7);ctx.fill();ctx.fillStyle='#c8634d';ctx.fillRect(10,-2,2,2);ctx.restore()}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.angle);let bob=Math.sin(player.walk)*1.4;ctx.fillStyle='#0a0d0a77';ctx.beginPath();ctx.ellipse(0,9,16,9,0,0,7);ctx.fill();ctx.strokeStyle='#242923';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(0,1,0);ctx.lineTo(10,8+bob);ctx.moveTo(0,1);ctx.lineTo(-9,8-bob);ctx.stroke();ctx.fillStyle='#7a8061';ctx.beginPath();ctx.ellipse(0,0,8,11,0,0,7);ctx.fill();ctx.fillStyle='#a5a17e';ctx.beginPath();ctx.arc(8,-1,5,0,7);ctx.fill();ctx.fillStyle='#374538';ctx.fillRect(-5,-6,9,9);ctx.strokeStyle='rgba(222,224,175,.75)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(11,-1);ctx.lineTo(28,0);ctx.stroke();ctx.restore();ctx.strokeStyle='rgba(213,221,166,.18)';ctx.beginPath();ctx.arc(player.x,player.y,49,0,Math.PI*2);ctx.stroke()}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,cw,ch);ctx.save();ctx.translate(-camera.x,-camera.y);drawGround();for(let t of trees)drawTree(t);for(let b of buildings)drawBuilding(b);for(let l of loot)if(l.active)drawLoot(l);for(let z of infected)drawInfected(z);drawPlayer();ctx.restore();
// dusk / night exposure with a subtle surviving pool of visibility around the survivor
let darkness=clamp((Math.cos((time-12)/24*Math.PI*2)+.18)*.46,0,.54);if(darkness>.015){let g=ctx.createRadialGradient(cw/2,ch/2,80,cw/2,ch/2,Math.max(cw,ch)*.72);g.addColorStop(0,`rgba(8,13,16,${darkness*.36})`);g.addColorStop(.28,`rgba(8,13,16,${darkness*.55})`);g.addColorStop(1,`rgba(5,9,12,${darkness})`);ctx.fillStyle=g;ctx.fillRect(0,0,cw,ch);if(flash){let f=ctx.createRadialGradient(cw/2,ch/2,20,cw/2,ch/2,320);f.addColorStop(0,'rgba(222,226,181,.24)');f.addColorStop(1,'rgba(222,226,181,0)');ctx.fillStyle=f;ctx.fillRect(0,0,cw,ch)}}if(weather==='LIGHT RAIN'){ctx.strokeStyle='rgba(205,219,206,.19)';ctx.lineWidth=1;for(let i=0;i<45;i++){let x=(i*137+performance.now()*.16)%cw,y=(i*89+performance.now()*.38)%ch;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+10);ctx.stroke()}}drawMini()}
